import{_ as a,O as n,H as o,f as s,i as r,k as l,b as i}from"./chunks/framework.DfbB1OsU.js";const b=JSON.parse('{"title":"Large events will be allowed soon, but will people show up?","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Large events will be allowed soon, but will people show up? | trendEcon"}],["meta",{"property":"og:description","content":"Daily economic indicators from Google searches"}],["meta",{"property":"og:url","content":"https://www.trendecon.org/blog/large-events"}],["meta",{"name":"twitter:title","content":"Large events will be allowed soon, but will people show up? | trendEcon"}],["meta",{"name":"twitter:description","content":"Daily economic indicators from Google searches"}]]},"headers":[],"relativePath":"blog/large-events.md","filePath":"blog/large-events.md"}'),d={name:"blog/large-events.md"};function h(p,e,c,w,u,m){const t=n("SeriesChart");return o(),s("div",null,[e[0]||(e[0]=r('<h1 id="large-events-will-be-allowed-soon-but-will-people-show-up" tabindex="-1">Large events will be allowed soon, but will people show up? <a class="header-anchor" href="#large-events-will-be-allowed-soon-but-will-people-show-up" aria-label="Permalink to &quot;Large events will be allowed soon, but will people show up?&quot;">​</a></h1><div class="byline"><span class="byline-author">Stefan Legge</span><span class="byline-date">24 August 2020</span></div><p>On 12 August 2020 the Federal Council <a href="https://www.srf.ch/news/schweiz/grossanlaesse-masken-kredite-das-hat-der-bundesrat-entschieden" target="_blank" rel="noreferrer">announced</a> that from October, large events with more than a thousand participants would be allowed again. This was another round of easing the Covid-19 restrictions imposed in March. Many companies, sports clubs and event organisers were relieved to finally see light at the end of the tunnel.</p><p>But just because large events are allowed does not mean people will attend them. The number of daily new Covid-19 cases had been rising for weeks, and many, though not all, people in Switzerland still tried to avoid large gatherings. A <a href="https://www.nber.org/papers/w27650" target="_blank" rel="noreferrer">U.S. study</a> shows that reopening restaurants after lockdowns led customers to believe it was safe to eat out again. Allowing large events may send a similar signal of safety. So did the announcement change people&#39;s minds?</p><p>With trendEcon we can see how Google search frequencies evolved over the past days, weeks and months. As keywords we use <em>Festival</em>, <em>Tickets kaufen</em> (buy tickets), <em>Hallenstadion</em> (a Zurich venue), <em>Letzigrund</em> (a Zurich stadium) and <em>Konzert</em> (concert). For none of them do the data show a positive impact of the announcement. Swiss people did not rush to find events and buy tickets. There are many possible reasons: people remained worried about the virus, the perceived economic situation was still worse than before the pandemic, and organisers themselves hesitated to plan for 2020. The Hallenstadion Zurich listed only seven events for the rest of the year.</p>',5)),l(t,{src:"https://cdn.jsdelivr.net/gh/trendecon/media-content@master/data_examples/article_2.csv",ids:["Konzert","Festival","Tickets kaufen","Hallenstadion"],from:"2020-01-01",eventset:"reopening",title:"Searches related to large events",subtitle:"2020; dashed lines mark Swiss reopening phases"}),e[1]||(e[1]=i("p",null,"The coming weeks would show whether demand for large events picked up as Switzerland approached the October relaunch. If not, that light at the end of the tunnel might not be too bright after all.",-1))])}const v=a(d,[["render",h]]);export{b as __pageData,v as default};
